from dataclasses import dataclass
from typing import Any, Callable, List


@dataclass
class TaskResult:
    status: str
    result: Any = None
    error: str = None
    func_name: str = None


class TaskRunner:
    def __init__(self) -> None:
        self._tasks: List[tuple] = []
        self._results: List[TaskResult] = []

    def add_task(self, func: Callable, *args, **kwargs) -> None:
        self._tasks.append((func, args, kwargs))

    def run(self) -> List[TaskResult]:
        self._results = []
        for func, args, kwargs in self._tasks:
            try:
                result = func(*args, **kwargs)
                self._results.append(
                    TaskResult(status="ok", result=result, func_name=func.__name__)
                )
            except Exception as e:
                self._results.append(
                    TaskResult(status="error", error=str(e), func_name=func.__name__)
                )
        return self._results

    def get_errors(self) -> List[TaskResult]:
        return [r for r in self._results if r.status == "error"]

    def get_successes(self) -> List[TaskResult]:
        return [r for r in self._results if r.status == "ok"]

    @property
    def summary(self) -> dict:
        total = len(self._results)
        successes = len(self.get_successes())
        errors = len(self.get_errors())
        return {
            "total": total,
            "successes": successes,
            "errors": errors,
            "success_rate": successes / total if total else 0.0,
        }
